:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #6c5ce7;
  --primary-light: #a29bfe;
  --accent: #00cec9;
  --text: #f5f6fa;
  --text-muted: #b2bec3;
  --card-back: #3d3d5c;
  --card-radius: 12px;
  --shadow: 0 4px 12px rgba(0, 0, 0, 0.3);
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-container {
  width: 100%;
  max-width: 560px;
  background: var(--surface);
  border-radius: 20px;
  padding: 24px;
  box-shadow: var(--shadow);
}

.game-header {
  text-align: center;
  margin-bottom: 20px;
}

.game-header h1 {
  font-size: 1.6rem;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--primary-light);
}

.moves-display {
  font-size: 1.1rem;
  color: var(--text-muted);
  font-weight: 600;
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-bottom: 20px;
}

.card {
  aspect-ratio: 1 / 1;
  border-radius: var(--card-radius);
  background: var(--card-back);
  border: 2px solid transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: transparent;
  transition: transform 0.15s ease, background 0.25s ease, border-color 0.15s ease;
  user-select: none;
  padding: 0;
  position: relative;
  box-shadow: var(--shadow);
}

.card:hover:not(.matched):not(.flipped) {
  transform: scale(1.05);
  border-color: var(--primary-light);
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.card:active:not(.matched):not(.flipped) {
  transform: scale(0.97);
}

.card.flipped,
.card.matched {
  background: var(--primary);
  color: var(--text);
  cursor: default;
}

.card.matched {
  border-color: var(--accent);
  opacity: 0.85;
}

.card.flipped:not(.matched) {
  border-color: var(--primary-light);
}

/* Card color variants */
.card[data-color="0"] { --card-color: #e74c3c; }
.card[data-color="1"] { --card-color: #3498db; }
.card[data-color="2"] { --card-color: #2ecc71; }
.card[data-color="3"] { --card-color: #f1c40f; }
.card[data-color="4"] { --card-color: #9b59b6; }
.card[data-color="5"] { --card-color: #e67e22; }
.card[data-color="6"] { --card-color: #1abc9c; }
.card[data-color="7"] { --card-color: #e84393; }

.card.flipped[data-color],
.card.matched[data-color] {
  background: var(--card-color);
}

.win-message {
  text-align: center;
  padding: 16px;
  background: var(--primary);
  border-radius: var(--card-radius);
  margin-bottom: 20px;
  box-shadow: var(--shadow);
}

.win-message p {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.btn {
  display: inline-block;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font);
  color: var(--text);
  background: var(--primary);
  border: 2px solid transparent;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, border-color 0.2s;
  box-shadow: var(--shadow);
}

.btn:hover {
  background: var(--primary-light);
  border-color: var(--accent);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.game-footer {
  text-align: center;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  .game-board {
    gap: 8px;
  }
  .card {
    font-size: 1.2rem;
  }
  .game-header h1 {
    font-size: 1.3rem;
  }
}

(function () {
  'use strict';

  const TOTAL_PAIRS = 8;
  const COLORS = [
    '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
    '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
  ];

  const boardEl = document.getElementById('game-board');
  const moveCounterEl = document.getElementById('move-counter');
  const winMessageEl = document.getElementById('win-message');
  const newGameBtn = document.getElementById('new-game-btn');
  const newGameBtnFooter = document.getElementById('new-game-btn-footer');

  let cards = [];
  let flipped = [];
  let moves = 0;
  let matchedCount = 0;
  let lock = false;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function createDeck() {
    const deck = [];
    for (let i = 0; i < TOTAL_PAIRS; i++) {
      deck.push({ colorIndex: i, color: COLORS[i], matched: false });
      deck.push({ colorIndex: i, color: COLORS[i], matched: false });
    }
    return shuffle(deck);
  }

  function renderBoard() {
    boardEl.innerHTML = '';
    cards.forEach((card, index) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'card';
      btn.dataset.index = index;
      btn.dataset.color = card.colorIndex;
      btn.setAttribute('role', 'gridcell');
      btn.setAttribute('aria-label', 'Card ' + (index + 1) + ', face down');
      btn.addEventListener('click', onCardClick);
      boardEl.appendChild(btn);
    });
  }

  function onCardClick(e) {
    const btn = e.currentTarget;
    const index = Number(btn.dataset.index);
    const card = cards[index];

    if (lock || card.matched || flipped.includes(index)) return;

    flipCard(btn, card);
    flipped.push(index);

    if (flipped.length === 2) {
      moves++;
      updateMoveCounter();
      checkMatch();
    }
  }

  function flipCard(btn, card) {
    btn.classList.add('flipped');
    btn.setAttribute('aria-label', 'Card ' + (Number(btn.dataset.index) + 1) + ', color ' + card.colorIndex);
    btn.style.backgroundColor = card.color;
  }

  function unflipCard(btn, card) {
    btn.classList.remove('flipped');
    btn.setAttribute('aria-label', 'Card ' + (Number(btn.dataset.index) + 1) + ', face down');
    btn.style.backgroundColor = '';
  }

  function checkMatch() {
    const [i1, i2] = flipped;
    const card1 = cards[i1];
    const card2 = cards[i2];
    const btn1 = boardEl.children[i1];
    const btn2 = boardEl.children[i2];

    if (card1.colorIndex === card2.colorIndex) {
      card1.matched = true;
      card2.matched = true;
      btn1.classList.add('matched');
      btn2.classList.add('matched');
      btn1.setAttribute('aria-label', 'Card ' + (i1 + 1) + ', matched');
      btn2.setAttribute('aria-label', 'Card ' + (i2 + 1) + ', matched');
      matchedCount++;
      flipped = [];
      if (matchedCount === TOTAL_PAIRS) {
        showWin();
      }
    } else {
      lock = true;
      setTimeout(() => {
        unflipCard(btn1, card1);
        unflipCard(btn2, card2);
        flipped = [];
        lock = false;
      }, 800);
    }
  }

  function updateMoveCounter() {
    moveCounterEl.textContent = 'Moves: ' + moves;
  }

  function showWin() {
    winMessageEl.hidden = false;
    winMessageEl.querySelector('p').textContent =
      'You win! All pairs matched in ' + moves + ' moves.';
    winMessageEl.querySelector('button').focus();
  }

  function resetGame() {
    cards = createDeck();
    flipped = [];
    moves = 0;
    matchedCount = 0;
    lock = false;
    winMessageEl.hidden = true;
    updateMoveCounter();
    renderBoard();
  }

  newGameBtn.addEventListener('click', resetGame);
  newGameBtnFooter.addEventListener('click', resetGame);

  resetGame();
})();
